const fixture=Object.keys(raw).length===0;
const instruction=String(fixture?'Pridaj navigáciu medzi dokumentmi na stránke Jobcenter: jeden zoznam najviac 10 odkazov na sekcie.':raw.instruction||'').trim();
const quantity=fixture?1:raw.quantity;
const request_id=fixture?'test-order-'+$execution.id:String(raw.request_id||'');
if(!instruction||instruction.length>4000||!Number.isSafeInteger(quantity)||quantity<1||quantity>100||!/^[-A-Za-z0-9_.]{3,100}$/.test(request_id)) throw new Error('Invalid TEST request: provide request_id, instruction and integer quantity');
if(!fixture&&raw.environment!=='TEST')throw new Error('Only TEST requests allowed');
// Single trusted internal test identity. No public webhook or customer-supplied tenant.
return [{json:{request_id,client_id:'test-owner',site_url:'https://www.foxprof.club/jobcenter/',instruction,quantity,environment:'TEST',pricebook_version:'TEST-2026-11-v1'}}];

