CREATE SCHEMA IF NOT EXISTS wdfox_test;
CREATE TABLE IF NOT EXISTS wdfox_test.client_requests (
 request_id text PRIMARY KEY,client_id text NOT NULL,site_url text NOT NULL,
 instruction text NOT NULL,quantity integer NOT NULL CHECK(quantity>0),
 environment text NOT NULL CHECK(environment='TEST'),pricebook_version text NOT NULL,
 status text NOT NULL DEFAULT 'RECEIVED',quote_report jsonb,
 created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);

WITH inserted AS (
 INSERT INTO wdfox_test.client_requests (request_id,client_id,site_url,instruction,quantity,environment,pricebook_version)
 VALUES ($1,$2,$3,$4,$5,'TEST',$6) ON CONFLICT (request_id) DO NOTHING RETURNING *
)
SELECT * FROM inserted UNION ALL
SELECT * FROM wdfox_test.client_requests WHERE request_id=$1 AND NOT EXISTS(SELECT 1 FROM inserted);

