const expected=$('Validate TEST Order').first().json;
for(const key of ['request_id','client_id','site_url','instruction','quantity','environment','pricebook_version'])if($json[key]!==expected[key])throw new Error('Existing request_id belongs to a different request; use a new ID');
return [{json:expected}];

const req=$('Validate TEST Order').first().json;
const r=$json;
if(r.request_id!==req.request_id||r.instruction!==req.instruction||r.environment!=='TEST'||r.pricebook_version!==req.pricebook_version||r.billing_enabled!==false||r.customer_approved!==false||r.production_touched!==false||!['TEST_QUOTE_DRAFT','NEEDS_CLARIFICATION','PRICE_NOT_AVAILABLE'].includes(r.status))throw new Error('Unexpected price report');
if(r.status==='TEST_QUOTE_DRAFT'&&(r.quantity!==req.quantity||!Number.isSafeInteger(r.total_excl_vat_cents)||r.total_excl_vat_cents<=0||r.payable_total_cents!==null))throw new Error('Invalid draft amount');
return [{json:{request_id:req.request_id,client_id:req.client_id,status:r.status==='TEST_QUOTE_DRAFT'?'DRAFT_REQUIRES_SCOPE_REVIEW':r.status,report:r}}];
